const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert');
const request = require('supertest');
const { installMock, resetMockDb } = require('./mockDb');

process.env.JWT_SECRET = 'x'.repeat(32);
installMock();
const app = require('../src/app');

describe('Task Manager Application Tests', () => {
  beforeEach(() => {
    resetMockDb();
  });

  it('should reject signup with short password', async () => {
    const res = await request(app).post('/api/auth/signup').send({ email: 'alice@example.com', password: '123' });
    assert.strictEqual(res.status, 400);
  });

  it('should sign up and allow authenticated me lookup', async () => {
    const signupRes = await request(app).post('/api/auth/signup').send({ email: 'alice@example.com', password: 'password123' });
    assert.strictEqual(signupRes.status, 201);
    const meRes = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${signupRes.body.token}`);
    assert.strictEqual(meRes.status, 200);
    assert.strictEqual(meRes.body.user.email, 'alice@example.com');
  });
});

const api = {
  async request(endpoint, options = {}) {
    const config = {
      credentials: 'same-origin',
      headers: {
        'Content-Type': 'application/json',
        ...options.headers
      },
      ...options
    };

    if (config.body && typeof config.body === 'object' && !(config.body instanceof FormData)) {
      config.body = JSON.stringify(config.body);
    }

    const response = await fetch(endpoint, config);
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      const error = new Error(data.error || 'Something went wrong');
      error.status = response.status;
      error.data = data;
      throw error;
    }

    return data;
  },

  async signup(email, password) {
    return this.request('/api/auth/signup', { method: 'POST', body: { email, password } });
  },

  async login(email, password) {
    return this.request('/api/auth/login', { method: 'POST', body: { email, password } });
  },

  async logout() {
    return this.request('/api/auth/logout', { method: 'POST' });
  },

  async getMe() {
    return this.request('/api/auth/me', { method: 'GET' });
  },

  async getTasks(status = '') {
    const query = status && status !== 'all' ? `?status=${encodeURIComponent(status)}` : '';
    return this.request(`/api/tasks${query}`, { method: 'GET' });
  },

  async getTask(id) {
    return this.request(`/api/tasks/${id}`, { method: 'GET' });
  },

  async createTask(taskData) {
    return this.request('/api/tasks', { method: 'POST', body: taskData });
  },

  async updateTask(id, taskData) {
    return this.request(`/api/tasks/${id}`, { method: 'PUT', body: taskData });
  },

  async deleteTask(id) {
    return this.request(`/api/tasks/${id}`, { method: 'DELETE' });
  }
};

